import timingJson from "./narration-timing.json";
import {
  CUT_SCRIPTS,
  SPEAKER_LABELS,
  type DemoCut,
  type DemoLocale,
  type SceneKey,
  type Segment,
} from "./cuts";

export type { DemoCut, DemoLocale, SceneKey } from "./cuts";

type TimingFile = Record<
  DemoCut,
  Record<
    DemoLocale,
    { duration: number; segments: { start: number; end: number }[] }[]
  >
>;

/**
 * Generated by scripts/generate-demo-narration.py from the measured audio, so
 * every on-screen beat is keyed to when its line is actually spoken.
 */
const TIMING = timingJson as TimingFile;

/** A script line with its measured start/end, in seconds from scene start. */
export type TimedSegment = Segment & { start: number; end: number };

export type SceneWindow = {
  /** 1-based position in the cut; also the narration file number. */
  index: number;
  key: SceneKey;
  start: number;
  end: number;
  duration: number;
  segments: TimedSegment[];
};

export function isDemoCut(value: string | null | undefined): value is DemoCut {
  return value === "platform" || value === "missed-call";
}

function buildScenes(cut: DemoCut, locale: DemoLocale): SceneWindow[] {
  const script = CUT_SCRIPTS[cut];
  const timing = TIMING[cut]?.[locale];
  if (!timing || timing.length !== script.length) {
    throw new Error(
      `narration-timing.json is out of date for ${cut}/${locale}; regenerate the demo narration`,
    );
  }
  let cursor = 0;
  return script.map((scene, i) => {
    const t = timing[i];
    const segments = scene.segments[locale].map((segment, j) => ({
      ...segment,
      start: t.segments[j]?.start ?? 0,
      end: t.segments[j]?.end ?? t.duration,
    }));
    const window: SceneWindow = {
      index: i + 1,
      key: scene.key,
      start: cursor,
      end: cursor + t.duration,
      duration: t.duration,
      segments,
    };
    cursor += t.duration;
    return window;
  });
}

const SCENES = new Map<string, SceneWindow[]>();

export function scenesFor(cut: DemoCut, locale: DemoLocale): SceneWindow[] {
  const key = `${cut}/${locale}`;
  let scenes = SCENES.get(key);
  if (!scenes) {
    scenes = buildScenes(cut, locale);
    SCENES.set(key, scenes);
  }
  return scenes;
}

export function totalDurationSec(cut: DemoCut, locale: DemoLocale): number {
  const scenes = scenesFor(cut, locale);
  return scenes[scenes.length - 1].end;
}

export function totalDurationMs(cut: DemoCut, locale: DemoLocale): number {
  return totalDurationSec(cut, locale) * 1000;
}

export function sceneAt(
  timeSec: number,
  cut: DemoCut,
  locale: DemoLocale,
): SceneWindow {
  const scenes = scenesFor(cut, locale);
  return (
    scenes.find((s) => timeSec >= s.start && timeSec < s.end) ??
    scenes[scenes.length - 1]
  );
}

/** Seconds since a line started; negative until it does. */
export function sinceLine(scene: SceneWindow, sec: number, line: number) {
  const segment = scene.segments[line];
  return segment ? sec - segment.start : -1;
}

export type CaptionCue = {
  start: number;
  end: number;
  text: string;
  highlights?: string[];
  /**
   * Dialogue is already shown as call bubbles, so the burned-in overlay skips
   * it; the VTT track still carries it, labelled by speaker.
   */
  onScreen: boolean;
  vttText: string;
};

/** Splits narration into sentence-sized caption chunks (min ~40 chars). */
function chunkText(text: string): string[] {
  const parts = text.match(/[^.!?:;]+[.!?:;]*\s*/g) ?? [text];
  const chunks: string[] = [];
  for (const part of parts) {
    const last = chunks[chunks.length - 1];
    if (last !== undefined && (last.length < 40 || part.trim().length < 18)) {
      chunks[chunks.length - 1] = last + part;
    } else {
      chunks.push(part);
    }
  }
  return chunks.map((c) => c.trim()).filter(Boolean);
}

const CAPTIONS = new Map<string, CaptionCue[]>();

export function captionsFor(cut: DemoCut, locale: DemoLocale): CaptionCue[] {
  const key = `${cut}/${locale}`;
  const cached = CAPTIONS.get(key);
  if (cached) return cached;

  const cues: CaptionCue[] = [];
  const scenes = scenesFor(cut, locale);
  for (const scene of scenes) {
    scene.segments.forEach((segment, i) => {
      const next = scene.segments[i + 1];
      const start = scene.start + segment.start;
      // Captions hold until the next line (or the scene) takes over.
      const end = scene.start + (next ? next.start : scene.duration);
      const speaker = SPEAKER_LABELS[locale][segment.voice];

      if (segment.voice !== "narrator" && segment.voice !== "none") {
        cues.push({
          start,
          end,
          text: segment.text,
          onScreen: false,
          vttText: `${speaker}: ${segment.text}`,
        });
        return;
      }

      const chunks = chunkText(segment.text);
      const spoken = scene.start + segment.end - start;
      const total = chunks.reduce((n, c) => n + c.length, 0);
      let cursor = start;
      chunks.forEach((chunk, j) => {
        const isLast = j === chunks.length - 1;
        const chunkEnd = isLast ? end : cursor + (spoken * chunk.length) / total;
        cues.push({
          start: cursor,
          end: chunkEnd,
          text: chunk,
          highlights: segment.highlights?.filter((h) =>
            chunk.toLowerCase().includes(h.toLowerCase()),
          ),
          onScreen: true,
          vttText: chunk,
        });
        cursor = chunkEnd;
      });
    });
  }
  CAPTIONS.set(key, cues);
  return cues;
}

export function captionAt(
  timeSec: number,
  cut: DemoCut,
  locale: DemoLocale,
): CaptionCue | null {
  return (
    captionsFor(cut, locale).find(
      (c) => c.onScreen && timeSec >= c.start && timeSec < c.end,
    ) ?? null
  );
}

export function formatClock(ms: number): string {
  const total = Math.max(0, Math.floor(ms / 1000));
  const m = Math.floor(total / 60);
  const s = total % 60;
  return `${m}:${s.toString().padStart(2, "0")}`;
}

export type SfxSound = "ring" | "missed" | "sms" | "notify" | "confirm" | "answer";

/**
 * SFX cues: a scene key plus either a fraction of that scene, or an anchor on
 * one of its spoken lines (so effects stay on the beat in both locales).
 */
type SfxAt = number | { line: number; edge: "start" | "end"; offset: number };

const SFX_CUES: Record<DemoCut, { sound: SfxSound; scene: SceneKey; at: SfxAt }[]> = {
  platform: [
    { sound: "ring", scene: "contractor", at: 0.05 },
    { sound: "ring", scene: "contractor", at: 0.3 },
    { sound: "missed", scene: "contractor", at: 0.62 },
    { sound: "ring", scene: "answer", at: 0.12 },
    { sound: "answer", scene: "answer", at: 0.42 },
    { sound: "notify", scene: "transfer", at: { line: 0, edge: "start", offset: 1 } },
    { sound: "ring", scene: "transfer", at: { line: 1, edge: "end", offset: -0.6 } },
    { sound: "confirm", scene: "transfer", at: { line: 1, edge: "end", offset: 0.9 } },
    { sound: "notify", scene: "workspace", at: 0.06 },
    { sound: "confirm", scene: "workspace", at: 0.72 },
    { sound: "sms", scene: "followUps", at: 0.12 },
    { sound: "sms", scene: "followUps", at: 0.45 },
  ],
  "missed-call": [
    { sound: "ring", scene: "contractor", at: 0.05 },
    { sound: "ring", scene: "contractor", at: 0.3 },
    { sound: "missed", scene: "contractor", at: 0.6 },
    { sound: "sms", scene: "textBack", at: 0.16 },
    { sound: "sms", scene: "textBack", at: 0.62 },
    { sound: "notify", scene: "leadCaptured", at: 0.06 },
    { sound: "sms", scene: "quoteFollowUp", at: 0.2 },
    { sound: "sms", scene: "quoteFollowUp", at: 0.46 },
  ],
};

export function sfxMarks(
  cut: DemoCut,
  locale: DemoLocale,
): { key: string; sound: SfxSound; start: number; end: number }[] {
  const scenes = scenesFor(cut, locale);
  return SFX_CUES[cut].map(({ sound, scene, at }, i) => {
    const window = scenes.find((s) => s.key === scene)!;
    let offset: number;
    if (typeof at === "number") {
      offset = at * window.duration;
    } else {
      const line = window.segments[at.line];
      offset = (line ? line[at.edge] : 0) + at.offset;
    }
    const start = window.start + offset;
    return { key: `${sound}-${i}`, sound, start, end: start + 1.2 };
  });
}

